<script setup lang="ts">
import { computed,nextTick,onBeforeUnmount,onMounted,ref,watch } from 'vue';import { useRouter } from 'vue-router';
import { request,errorText,uid,APIError } from '../api';import { explicitRejection } from '../workflow';import { session } from '../session';
import { resourceActions,sections,initialFields,buildOperation,operationData,objectName,resourceSection,resourceTree,supports,type ResourceSection,type ResourceField,type FieldValue } from '../resources';
import type { Node,Page,NodeResourcesState,ConfigurationState,Change,Plan,Job,Operation } from '../types';import ResourceQuery from './resource-query.vue';
const nodes=ref<Node[]>([]);const nodeId=ref(sessionStorage.getItem('sdn.resource.node')||'');const resources=ref<NodeResourcesState>();const change=ref<Change>();const plan=ref<Plan>();
const section=ref<ResourceSection>('tenant');const actionId=ref('tenant-create');const values=ref<Record<string,FieldValue>>({});
const busy=ref(false);const error=ref('');const notice=ref('');const recoveryId=ref(sessionStorage.getItem('sdn.change')||'');const pendingCommit=ref(sessionStorage.getItem('sdn.commit')||'');
const router=useRouter();let active=new AbortController();let generation=0;
const node=computed(()=>nodes.value.find(n=>n.nodeId===nodeId.value));
const objects=computed(()=>resources.value?.resources?.objects||[]);const tree=computed(()=>resourceTree(objects.value));
const actions=computed(()=>resourceActions.filter(a=>a.section===section.value||(section.value==='bridge'&&a.code==='ADDRESS')));
const action=computed(()=>resourceActions.find(a=>a.id===actionId.value));
const rows=computed(()=>objects.value.filter(o=>resourceSection(o)===section.value||(section.value==='bridge'&&o.code==='ADDRESS'&&objects.value.some(b=>b.code==='BD'&&operationData(b).name===operationData(o).interface))));
const admin=computed(()=>session.role==='admin');const openChange=computed(()=>!!change.value&&!change.value.frozen&&!change.value.aborted);
const mutable=computed(()=>admin.value&&openChange.value&&!pendingCommit.value&&resources.value?.mode==='resources'&&!!resources.value.adopted&&!busy.value);
const supported=computed(()=>!!action.value&&supports(node.value,action.value.code));
// Element Plus 2.14 writes InputNumber aria-disabled only when it mounts.
// Key numeric controls by effective disabled state so keyboard/AT users see
// the same enabled state as the native input after Begin or a saved edit.
function choiceSupported(id:string){const a=resourceActions.find(v=>v.id===id);return !!a&&supports(node.value,a.code);}
watch(section,()=>{actionId.value=actions.value[0]?.id||'';});watch(actionId,()=>{if(action.value)values.value=initialFields(action.value);},{immediate:true});
watch(nodeId,()=>{sessionStorage.setItem('sdn.resource.node',nodeId.value);plan.value=undefined;values.value=action.value?initialFields(action.value):{};void loadResources();});
function references(field:ResourceField):string[]{const code=field.reference==='tenant'?'TENANT':field.reference==='bridge'?'BD':field.reference==='vxlan'?'VXLAN':'';return [...new Set(objects.value.filter(o=>code?o.code===code:['BD','VXLAN','INTERFACE'].includes(o.code)).map(o=>String(operationData(o).name||'')).filter(Boolean))].sort();}
function rowAction(row:Operation,deleteAction=false){return resourceActions.find(a=>a.code===row.code&&(deleteAction?['DELETE','UNBIND'].includes(a.action):a.action==='SET')&&a.data!=='bridgePolicy');}
async function selectRow(row:Operation,remove=false){const a=rowAction(row,remove);if(!a)return;section.value=a.section;await nextTick();actionId.value=a.id;await nextTick();const data=operationData(row);values.value=initialFields(a);const identity=['name','asn','vrf','interface','tenant','bridge','port','vni','prefix','family','protocol'];for(const f of a.fields){if((f.required||identity.includes(f.key))&&data[f.key]!==undefined)values.value[f.key]=data[f.key] as FieldValue;}document.getElementById('resource-form')?.scrollIntoView({behavior:'smooth',block:'start'});}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function accept(c:Change){change.value=c;plan.value=undefined;recoveryId.value=c.id;sessionStorage.setItem('sdn.change',c.id);}
async function fetchResources(){if(!nodeId.value)return;const selected=nodeId.value;const candidate=change.value?.id;const result=await request<NodeResourcesState>(`/nodes/${encodeURIComponent(selected)}/resources${candidate?'?changeId='+encodeURIComponent(candidate):''}`);if(selected===nodeId.value&&candidate===change.value?.id)resources.value=result;}
async function loadResources(){active.abort();active=new AbortController();const signal=active.signal;const mine=++generation;resources.value=undefined;if(!nodeId.value)return;const candidate=change.value?.id;try{const result=await request<NodeResourcesState>(`/nodes/${encodeURIComponent(nodeId.value)}/resources${candidate?'?changeId='+encodeURIComponent(candidate):''}`,{signal});if(mine===generation){resources.value=result;error.value='';}}catch(e){if(!signal.aborted&&mine===generation)error.value=errorText(e);}}
async function loadNodes(){const all:Node[]=[];let token='';do{const page=await request<Page<Node>>('/nodes?pageSize=200'+(token?'&pageToken='+encodeURIComponent(token):''));all.push(...page.items);token=page.nextPageToken;}while(token);nodes.value=all;if(!all.some(n=>n.nodeId===nodeId.value))nodeId.value=all[0]?.nodeId||'';}
async function refresh(){await run(async()=>{await loadNodes();if(change.value)accept(await request<Change>(`/changes/${encodeURIComponent(change.value.id)}`));await fetchResources();});}
async function create(){await run(async()=>{let pending=sessionStorage.getItem('sdn.begin');if(!pending){const desired=await request<ConfigurationState>('/desired');pending=JSON.stringify({baseRevision:desired.revision,requestId:uid()});sessionStorage.setItem('sdn.begin',pending);}const q=JSON.parse(pending);try{accept(await request<Change>('/changes',{method:'POST',body:q,key:q.requestId}));sessionStorage.removeItem('sdn.begin');await fetchResources();}catch(e){if(e instanceof APIError&&explicitRejection(e.status))sessionStorage.removeItem('sdn.begin');throw e;}});}
async function recover(){if(!recoveryId.value)return;await run(async()=>{accept(await request<Change>(`/changes/${encodeURIComponent(recoveryId.value)}`));await fetchResources();});}
async function stage(){await run(async()=>{if(!action.value||!change.value||!resources.value||!supported.value)throw new Error('当前节点或操作不支持配置');const operation=buildOperation(action.value,values.value);const selected=nodeId.value;const id=change.value.id;const body=action.value.id==='bridge-policy'?{editRevision:change.value.editRevision,bridgePolicies:[operationData(operation)]}:{editRevision:change.value.editRevision,operations:[operation]};try{accept(await request<Change>(`/changes/${encodeURIComponent(id)}/nodes/${encodeURIComponent(selected)}/resources`,{method:'PUT',body}));await fetchResources();notice.value='操作已加入候选，尚未下发。可继续添加其他操作，然后统一预览和提交。';}catch(e){plan.value=undefined;try{accept(await request<Change>(`/changes/${encodeURIComponent(id)}`));await fetchResources();notice.value='已重新读取候选。请核对资源与草稿版本：网络超时时操作可能已保存，避免重复创建。';}catch{notice.value='无法确认候选状态，请恢复候选后核对，不要重复创建。';}throw e;}});}
async function preview(){await run(async()=>{if(change.value)plan.value=await request<Plan>(`/changes/${encodeURIComponent(change.value.id)}/plan`,{method:'POST'});});}
function clearPending(){sessionStorage.removeItem('sdn.commit');pendingCommit.value='';}
async function commit(){await run(async()=>{let pending=pendingCommit.value;if(!pending){if(!change.value||!plan.value)return;pending=JSON.stringify({changeId:change.value.id,planId:plan.value.id,requestId:uid()});pendingCommit.value=pending;sessionStorage.setItem('sdn.commit',pending);}const q=JSON.parse(pending);try{const job=await request<Job>(`/changes/${encodeURIComponent(q.changeId)}/commit`,{method:'POST',body:{planId:q.planId,requestId:q.requestId},key:q.requestId});clearPending();await router.push({path:'/jobs',query:{id:job.id}});}catch(e){if(e instanceof APIError&&explicitRejection(e.status)){try{const c=await request<Change>(`/changes/${encodeURIComponent(q.changeId)}`);accept(c);if(c.jobId){clearPending();await router.push({path:'/jobs',query:{id:c.jobId}});return;}if(!c.frozen){clearPending();notice.value='提交被拒绝；需重新预览。基础版本冲突时请新建候选并重新合并。';throw e;}}catch(lookup){if(!pendingCommit.value)throw lookup;}}notice.value='提交结果未确认，已保留原幂等键。请重试原提交找回任务。';throw e;}});}
async function abort(){await run(async()=>{if(!change.value)return;await request(`/changes/${encodeURIComponent(change.value.id)}`,{method:'DELETE'});accept(await request<Change>(`/changes/${encodeURIComponent(change.value.id)}`));await fetchResources();});}
async function importResources(){await run(async()=>{if(!resources.value)return;const selected=nodeId.value;const storageKey='sdn.import.'+selected;let pending=sessionStorage.getItem(storageKey);if(!pending){pending=JSON.stringify({expectedAgentRevision:resources.value.agentRevision,requestId:uid()});sessionStorage.setItem(storageKey,pending);}const q=JSON.parse(pending);try{resources.value=await request<NodeResourcesState>(`/nodes/${encodeURIComponent(selected)}/resources/import`,{method:'POST',body:q,key:q.requestId});sessionStorage.removeItem(storageKey);notice.value='已验证并导入资源基线。请新建候选开始独立资源配置。';}catch(e){if(e instanceof APIError&&explicitRejection(e.status))sessionStorage.removeItem(storageKey);throw e;}});}
onMounted(()=>run(async()=>{if(recoveryId.value){try{accept(await request<Change>(`/changes/${encodeURIComponent(recoveryId.value)}`));}catch(e){notice.value='上次候选不可恢复：'+errorText(e);}}await loadNodes();await fetchResources();}));onBeforeUnmount(()=>active.abort());
</script>
<template><div class="panel"><div class="page-head"><div><h2>Agent 资源工作台</h2><p class="subtitle">独立配置 VRF、BD、接口、隧道与路由协议；多次编辑同一候选，再统一提交。</p></div><el-button :loading="busy" @click="refresh">刷新资源</el-button></div><div class="toolbar"><el-select v-model="nodeId" filterable :disabled="busy" aria-label="资源 Agent" placeholder="选择 Agent" style="min-width:320px"><el-option v-for="n in nodes" :key="n.nodeId" :value="n.nodeId" :label="`${n.name||n.nodeId} · ${n.role} · ${n.state}`"/></el-select><el-tag v-if="node">{{node.adopted?'已接管':'未接管'}}</el-tag><el-button link @click="router.push('/nodes')">节点与能力</el-button><el-button link @click="router.push('/changes')">高级 JSON 编辑器</el-button></div>
<el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="notice" :title="notice" type="info" :closable="false"/><el-alert v-if="!admin" title="当前为 viewer，只允许查看配置目标与运行状态。" type="info" :closable="false"/>
<div v-if="resources" class="resource-candidate"><p class="subtitle mono">节点 {{nodeId}} · Desired {{resources.desiredRevision}} · Agent {{resources.agentRevision}} · 模式 {{resources.mode}}</p><el-alert v-if="!resources.adopted" title="节点尚未接管，请先到节点页面核对版本并接管。" type="warning" :closable="false"/>
<template v-if="resources.mode!=='resources'"><el-alert title="该节点需要先验证并导入已有基线，才能使用独立资源编辑。导入不会下发网络配置；已有未提交候选请先丢弃。" type="warning" :closable="false"/><el-popconfirm v-if="admin" title="确认按当前 Agent 版本读回验证，并导入资源基线？" @confirm="importResources"><template #reference><el-button :disabled="busy||!resources.adopted||openChange||!!pendingCommit">验证并导入资源</el-button></template></el-popconfirm></template>
<div class="toolbar"><el-button v-if="admin" type="primary" :disabled="busy||openChange||!!pendingCommit||resources.mode!=='resources'||!resources.adopted" @click="create">新建资源候选</el-button><el-input v-model="recoveryId" aria-label="资源候选 ID" placeholder="已有候选 ID" style="max-width:330px"/><el-button :disabled="busy||!recoveryId" @click="recover">恢复候选</el-button></div>
<template v-if="change"><p class="subtitle mono">候选 {{change.id}} · 基础版本 {{change.baseRevision}} · 草稿版本 {{change.editRevision}} · {{change.aborted?'已丢弃':change.frozen?'已冻结':'尚未提交'}}</p><div class="toolbar"><el-button v-if="admin" :disabled="!mutable" @click="preview">预览全部变更</el-button><el-popconfirm v-if="admin" title="丢弃整个候选（包含其他节点的修改）？" @confirm="abort"><template #reference><el-button :disabled="!openChange||busy||!!pendingCommit">丢弃候选</el-button></template></el-popconfirm><el-button v-if="change.jobId" type="primary" link @click="router.push({path:'/jobs',query:{id:change.jobId}})">查看提交任务</el-button></div></template></div>
<el-tabs v-model="section" class="resource-tabs"><el-tab-pane v-for="s in sections" :key="s.id" :name="s.id" :label="s.label"/></el-tabs>
<template v-if="resources"><div v-if="section==='tenant'" class="panel"><h3>{{change?'候选':'配置目标'}}：租户 → 二层 BD → 三层接口</h3><p class="subtitle">空租户与未绑定资源均保留。BD 的三层地址与接口页使用同一对象。</p><el-tree v-if="tree.length" :data="tree" node-key="id" default-expand-all><template #default="{data}"><span><el-tag size="small" style="margin-right:8px">{{data.kind}}</el-tag>{{data.label}}</span></template></el-tree><el-empty v-else description="尚无 VRF / BD / VXLAN，可分别创建"/></div>
<div class="panel"><h3>{{change?'候选资源':'配置目标'}} · {{sections.find(s=>s.id===section)?.label}}</h3><el-table :data="rows" empty-text="当前节点没有此类配置目标"><el-table-column type="expand"><template #default="{row}"><pre class="code">{{JSON.stringify(operationData(row),null,2)}}</pre></template></el-table-column><el-table-column prop="code" label="资源类型" min-width="160"/><el-table-column label="对象" min-width="160"><template #default="{row}">{{objectName(row)}}</template></el-table-column><el-table-column label="配置字段" min-width="240" show-overflow-tooltip><template #default="{row}">{{JSON.stringify(operationData(row))}}</template></el-table-column><el-table-column v-if="admin" label="操作" width="150"><template #default="{row}"><el-button v-if="rowAction(row)" link type="primary" :disabled="!mutable" @click="selectRow(row)">修改</el-button><el-button v-if="rowAction(row,true)" link type="danger" :disabled="!mutable" @click="selectRow(row,true)">删除 / 解绑</el-button></template></el-table-column></el-table><template v-if="section==='bridge'"><h4>BD 抑制策略</h4><el-table :data="resources.resources.bridgePolicies||[]" empty-text="未配置 BD 级抑制策略"><el-table-column prop="bridge" label="BD"/><el-table-column label="ARP / ND 抑制"><template #default="{row}">{{row.neighSuppress?'启用':'关闭'}}</template></el-table-column></el-table></template></div>
<div v-if="admin" id="resource-form" class="panel"><h3>添加资源操作</h3><div class="toolbar"><el-select v-model="actionId" filterable aria-label="资源操作" style="min-width:350px"><el-option v-for="a in actions" :key="a.id" :value="a.id" :label="a.title+(choiceSupported(a.id)?'':'（能力未支持）')" :disabled="!choiceSupported(a.id)"/></el-select></div><el-alert v-if="!supported" title="此 Agent 未声明支持该操作及其回滚能力，不能提交。" type="warning" :closable="false"/><p v-if="action?.description" class="subtitle">{{action.description}}</p><p class="subtitle">可选字段留空表示保持已有值；布尔字段可明确选择关闭。先填写必填识别字段，再修改需要的属性。</p>
<el-form v-if="action" label-position="top" class="resource-form" :disabled="!mutable||!supported"><el-form-item v-for="field in action.fields" :key="action.id+'/'+field.key" :label="field.label" :required="field.required"><el-select v-if="field.type==='boolean'" v-model="values[field.key]" :aria-label="field.label" clearable placeholder="不修改 / 使用默认"><el-option label="启用 / 是" :value="true"/><el-option label="关闭 / 否" :value="false"/></el-select><el-select v-else-if="field.type==='select'" v-model="values[field.key]" :aria-label="field.label" clearable><el-option v-for="o in field.options" :key="o.value" :label="o.label" :value="o.value"/></el-select><el-input-number :key="String(!mutable||!supported)" v-else-if="field.type==='number'" v-model="values[field.key]" :aria-label="field.label" :min="field.min" :max="field.max" :controls="false" style="width:100%"/><el-select v-else-if="field.reference" v-model="values[field.key]" :aria-label="field.label" filterable allow-create default-first-option clearable placeholder="选择已有目标或输入实际名称"><el-option v-for="name in references(field)" :key="name" :value="name" :label="name"/></el-select><el-input v-else v-model="values[field.key]" :aria-label="field.label" :type="field.type==='list'?'textarea':'text'"/><p v-if="field.hint" class="muted">{{field.hint}}</p></el-form-item></el-form><el-button type="primary" :disabled="!mutable||!supported" :loading="busy" @click="stage">加入候选</el-button><span v-if="!openChange" class="muted"> 请先新建资源候选。</span></div></template>
<div v-if="plan" class="panel"><h2>下发计划</h2><p class="subtitle mono">{{plan.id}} · 基础 {{plan.baseRevision}} / 草稿 {{plan.editRevision}} · {{plan.nodes.length}} 个节点</p><el-alert v-for="warning in plan.warnings" :key="warning" :title="warning" type="warning" :closable="false"/><el-table :data="plan.nodes"><el-table-column type="expand"><template #default="{row}"><pre class="code">{{JSON.stringify(row.operations,null,2)}}</pre></template></el-table-column><el-table-column prop="nodeId" label="节点"/><el-table-column prop="expectedAgentRevision" label="Agent 基础版本"/><el-table-column label="操作数"><template #default="{row}">{{row.operations.length}}</template></el-table-column></el-table><el-popconfirm v-if="admin" title="确认提交整个候选并开始配置网络？" @confirm="commit"><template #reference><el-button type="primary" :disabled="busy||!!pendingCommit" style="margin-top:16px">提交配置</el-button></template></el-popconfirm></div>
<div v-if="pendingCommit&&admin" class="panel"><el-alert title="有待确认的提交请求，保留原幂等键以避免重复执行。" type="warning" :closable="false"/><el-button :loading="busy" @click="commit">重试原提交</el-button></div>
<ResourceQuery v-if="node" :node="node" :section="section"/>
</div></template>
